"""Run-length encoding helpers."""


def encode(s: str) -> str:
    """Encode runs of identical letters as the letter plus the run length."""
    if not s:
        return ''

    parts: list[str] = []
    run_char = s[0]
    run_length = 1

    for char in s[1:]:
        if char == run_char:
            run_length += 1
        else:
            parts.append(run_char if run_length == 1 else f'{run_char}{run_length}')
            run_char = char
            run_length = 1

    parts.append(run_char if run_length == 1 else f'{run_char}{run_length}')
    return ''.join(parts)


def decode(s: str) -> str:
    """Decode a run-length encoded string, including multi-digit run lengths."""
    parts: list[str] = []
    i = 0

    while i < len(s):
        char = s[i]
        i += 1

        start = i
        while i < len(s) and s[i].isdigit():
            i += 1

        run_length = int(s[start:i]) if i > start else 1
        parts.append(char * run_length)

    return ''.join(parts)
